// YinYang out of circles

function setup() {
	createCanvas(S = max(windowWidth, windowHeight), S);
	describe("YinYang made out of circles (and an arc)")
	background("rgb(73,60,62)"); // color("deepskyblue")
	noStroke();
	cB = color(0)
	cW = color(255)
	drawYingYang(S, S*0.1)
}

function draw() {
	background("deepskyblue")
	drawYingYang(S, abs(sin(frameCount*0.01))*S*0.1)
}

// https://commons.wikimedia.org/wiki/File:Yin_Yang_geometry.png
function drawYingYang(S, M = 0) {
	S -= M;
	const SH = S/2; // half
	const SQ = S/4; // quarter
	push();
	translate(SH+M/2, SH+M/2);
	fill(cW);
	circle(0, 0, S);
	fill(cB);
	arc(0, 0, S, S, -HALF_PI, HALF_PI);
	circle(0, SQ, SH);
	fill(cW);
	circle(0, -SQ, SH);
	circle(0, SQ, S/8);
	fill(cB);
	circle(0, -SQ, S/8);
	pop();
}
